# Identify frames: a frame is when we have 4 corners of same value at the corners of a 1-pixel border
# A closed frame means the border completely encloses interior pixels

def find_frames(grid, bg):
    h, w = len(grid), len(grid[0])
    frames = []

    # Look for rectangular frames of value v != bg
    for v in set() | {x for row in grid for x in row if x != bg}:
        # Find top-left corner of each potential frame
        for r in range(h):
            for c in range(w):
                if grid[r][c] == v:
                    # Check if this is top-left of a frame
                    # We need to find the extent of this frame
                    tr, tc, br, bc = r, c, r, c  # init

                    # Expand while we have value v and haven't gone beyond the top-bottom or left-right
                    while (r+1 < h and grid[r+1][c] == v):
                        r += 1
                    tr = grid[:r]
                    tr.append(grid[0])

        # Simpler: find top-left, bottom-right of each connected component
        pass

    # Detect frame as a hollow rectangle
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                val = grid[r][c]
                # Find horizontal extent at this row
                left, right = None, None
                for dc in range(c, w):
                    if grid[r][dc] == val:
                        if left is None:
                            left = dc
                        right = dc
                    elif grid[r][dc-1] == bg:
                        break
                # Find vertical extent at column c
                top, bottom = None, None
                for dr in range(r, h):
                    if grid[dr][c] == val:
                        if top is None:
                            top = dr
                        bottom = dr
                    elif grid[dr-1][c] == bg:
                        break

                if top and bottom and left and right and top <= bottom and left <= right:
                    frames.append((top, left, bottom, right, val))

    return frames

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # Find rectangular frames
    frames = []
    for v in set() | {x for row in grid for x in row if x != bg}:
        for r in range(h):
            for c in range(w):
                if grid[r][c] == v:
                    # Find the rectangular region containing this cell
                    # Expand in all 4 directions
                    left = c
                    while left > 0 and grid[r][left-1] != bg and grid[r][left-1] == grid[r][c]:
                        left -= 1
                    right = c
                    while right < w-1 and grid[r][right+1] != bg and grid[r][right+1] == grid[r][c]:
                        right += 1
                    top = r
                    while top > 0 and grid[top-1][c] != bg and grid[top-1][c] == grid[r][c]:
                        top -= 1
                    bottom = r
                    while bottom < h-1 and grid[bottom+1][c] != bg and grid[bottom+1][c] == grid[r][c]:
                        bottom += 1

                    # Check if this is a "frame" (hollow rectangle with interior)
                    if (top < bottom and left < right - 1):
                        frames.append((top, left, bottom, right, v))

    # Remove duplicate frames - merge overlapping ones
    unique_frames = []
    for t, l, b, r, v in frames:
        merged = False
        for i, (ut, ul, ub, ur, uv) in enumerate(unique_frames):
            if v == uv and t <= ub and b >= ut and l <= ur and r >= ul:
                unique_frames[i] = (min(ut, t), min(ul, l), max(ub, b), max(ur, r), v)
                merged = True
                break
        if not merged:
            unique_frames.append((t, l, b, r, v))

    # Fill interiors
    result = [row[:] for row in grid]

    # Process from smallest to largest frame
    sorted_frames = sorted(unique_frames, key=lambda x: (x[2]-x[0]+1, x[3]-x[1]+1))

    for top, left, bottom, right, v in sorted_frames:
        fill_val = 2 if v == 3 else 7

        # Fill interior (excluding the border)
        for rr in range(top+1, bottom):
            for cc in range(left+1, right):
                if result[rr][cc] == bg:
                    result[rr][cc] = fill_val

    return result

